// The sources added in M7's second round (2026-10-17): employers researched from their official
// sites (vacancy lists, feeds, sitemaps, robots.txt and terms of use), above all in countries that
// had no automatic source, with the same rules as the first sources (D52): never job boards, a
// source whose terms forbid automated access stays manual, and a manual source only where it is the
// only good source for its country. Inserted by the migration 20261017_210000_sources_round_2 with
// "Monitor on" unticked: each automatic source is run by hand first, then switched on. The list with
// every source as it stands after the round: docs/sources/sources-2026-10-17.csv.

export type SourceSeed2 = {
  key: string
  name: string
  /** The country's ISO code, for the report (the institution holds the country). */
  country: string
  /** The employer's ROR ID (the unit's, where ROR has one). */
  rorId: string | null
  kind: 'rss' | 'api' | 'page' | 'sitemap' | 'manual'
  apiFormat: 'greenhouse' | 'lever' | 'smartrecruiters' | null
  url: string
  moreUrls: string[]
  postingPattern: string | null
  allNeuroscience: boolean
  schedule: 'daily' | 'weekly' | 'monthly'
  termsUrl: string | null
  termsAutomation: 'not-stated' | 'allows' | 'forbids' | 'not-found'
  termsNote: string | null
  notes: string
}

